// Generated by Codex GPT-6-Astra with xHigh efforts.
`timescale 1ns/1ps
module tb;
    `ifdef CMOD_TEST_NO_PLL
        localparam H_ACTIVE=305, H_TOTAL=382, H_FRONT=8, H_SYNC=46, PIXEL_DIV=1;
        localparam real SYS_PERIOD=83.333334;
        localparam MIC_DIV=1024, DAC_DIV=256;
    `else
        localparam H_ACTIVE=640, H_TOTAL=800, H_FRONT=16, H_SYNC=96, PIXEL_DIV=4;
        localparam real SYS_PERIOD=10.0;
        localparam MIC_DIV=2048, DAC_DIV=2048;
    `endif
    reg sysclk=0;
    always #41.666667 sysclk=~sysclk;
    reg [1:0] btn=0;
    wire [1:0] led;
    wire led0_r, led0_g, led0_b;
    wire [7:0] ja;
    tri [43:0] gpio;
    reg uart_txd_in=1;
    wire uart_rxd_out;
    `ifndef CMOD_TEST_NO_TM1638
        pullup (gpio[21]);
    `endif
    wire pio27=gpio[22], pio28=gpio[23], pio29=gpio[24], pio30=gpio[25];
    wire pio32=gpio[27], pio33=gpio[28], pio34=gpio[29];
    reg mic_data=0;
    assign gpio[26]=mic_data;
    board_specific_top dut
    (
        .sysclk(sysclk), .btn(btn), .led(led),
        .led0_r(led0_r), .led0_g(led0_g), .led0_b(led0_b), .ja(ja),
        .uart_txd_in(uart_txd_in), .uart_rxd_out(uart_rxd_out),
        .pio1(gpio[0]), .pio2(gpio[1]), .pio3(gpio[2]), .pio4(gpio[3]), .pio5(gpio[4]), .pio6(gpio[5]),
        .pio7(gpio[6]), .pio8(gpio[7]), .pio9(gpio[8]), .pio10(gpio[9]), .pio11(gpio[10]), .pio12(gpio[11]),
        .pio13(gpio[12]), .pio14(gpio[13]), .pio17(gpio[14]), .pio18(gpio[15]), .pio19(gpio[16]), .pio20(gpio[17]),
        .pio21(gpio[18]), .pio22(gpio[19]), .pio23(gpio[20]), .pio26(gpio[21]), .pio27(gpio[22]), .pio28(gpio[23]),
        .pio29(gpio[24]), .pio30(gpio[25]), .pio31(gpio[26]), .pio32(gpio[27]), .pio33(gpio[28]), .pio34(gpio[29]),
        .pio35(gpio[30]), .pio36(gpio[31]), .pio37(gpio[32]), .pio38(gpio[33]), .pio39(gpio[34]), .pio40(gpio[35]),
        .pio41(gpio[36]), .pio42(gpio[37]), .pio43(gpio[38]), .pio44(gpio[39]), .pio45(gpio[40]), .pio46(gpio[41]),
        .pio47(gpio[42]), .pio48(gpio[43])
    );

    initial begin
        #40000000;
        $fatal(1,"Timeout");
    end

    // Independent I2S microphone: one dummy bit, then 24 MSB-first data bits.
    reg mic_ws=1;
    integer mic_bit=0;
    localparam [23:0] MIC_SAMPLE=24'h916ac3;
    always @ (negedge pio29) begin
        if(pio30!=mic_ws) begin
            mic_ws=pio30;
            mic_bit=0;
            mic_data=0;
        end else begin
            mic_bit=mic_bit+1;
            mic_data=(!pio30 && mic_bit>=1 && mic_bit<=24) ? MIC_SAMPLE[24-mic_bit] : 1'b0;
        end
    end

    reg dac_ws=0;
    integer dac_bit=0, dac_words=0;
    reg [31:0] dac_word=0;
    always @ (posedge pio32) begin
        if (pio34!=dac_ws) begin
            // In I2S the old slot's LSB overlaps the new LRCLK state.
            dac_word={dac_word[30:0],pio33};
            if(dac_words>=2 && dac_word!==32'h5a3c0000)
                $fatal(1,"I2S slot data/alignment: %h",dac_word);
            dac_words=dac_words+1;
            dac_ws=pio34;
            dac_bit=0;
            dac_word=0;
        end else begin
            dac_bit=dac_bit+1;
            dac_word={dac_word[30:0],pio33};
        end
    end

    integer cycles, pixels, active_pixels, hs_pixels, vs_lines;
    integer last_x, last_y;
    realtime last_hs=0, last_mic_ws=0, last_dac_ws=0;
    integer hs_periods=0, mic_periods=0, dac_periods=0;

    task check_period(input realtime elapsed, input realtime expected);
        if (elapsed < expected-1.0 || elapsed > expected+1.0)
            $fatal(1,"Clock period %0.3f ns, expected %0.3f ns",elapsed,expected);
    endtask

    `ifdef CMOD_TEST_NO_TM1638
    task check_buttons(input [1:0] pressed);
        // Move inputs between clock edges and check both synchronizer stages.
        @(negedge dut.clk);
        btn=pressed;
        @(negedge dut.clk);
        if(dut.key===pressed) $fatal(1,"Button synchronizer bypassed");
        @(negedge dut.clk);
        if(dut.key!==pressed || led!==pressed || dut.sw!=={6'b0,pressed})
            $fatal(1,"Onboard button/LED/momentary-switch mapping");
        repeat(16) begin
            @(negedge dut.clk);
            if(dut.rst!==0 || dut.locked!==1 || led0_g!==0 || led!==pressed)
                $fatal(1,"Lab buttons must not reset the design or clock manager");
        end
    endtask
    `endif

    // Measure actual pins in nanoseconds, independently of counter values.
    always @(negedge ja[7]) if (!dut.rst) begin
        if(last_hs!=0) begin
            check_period($realtime-last_hs,H_TOTAL*PIXEL_DIV*SYS_PERIOD);
            hs_periods=hs_periods+1;
        end
        last_hs=$realtime;
    end
    always @(posedge pio30) if (!dut.rst) begin
        if(last_mic_ws!=0) begin
            check_period($realtime-last_mic_ws,MIC_DIV*SYS_PERIOD);
            mic_periods=mic_periods+1;
        end
        last_mic_ws=$realtime;
    end
    always @(posedge pio34) if (!dut.rst) begin
        if(last_dac_ws!=0) begin
            check_period($realtime-last_dac_ws,DAC_DIV*SYS_PERIOD);
            dac_periods=dac_periods+1;
        end
        last_dac_ws=$realtime;
    end
    initial begin
        #1;
        if(dut.rst!==1 || led0_r!==0) $fatal(1,"Startup reset");
        wait(dut.locked===1);
        repeat(2) @(negedge dut.clk);
        if(dut.rst!==1) $fatal(1,"Reset released too early");
        repeat(2) @(negedge dut.clk);
        if(dut.rst!==0 || led0_g!==0 || led0_b!==1) $fatal(1,"Reset release / LED polarity");
        if(gpio[7:0]!==8'ha6) $fatal(1,"GPIO bit numbering");
        uart_txd_in=0; #1;
        if(uart_rxd_out!==0) $fatal(1,"USB UART direction");
        `ifdef CMOD_TEST_NO_TM1638
        if(dut.i_lab_top.w_key!=2 || dut.i_lab_top.w_led!=2)
            $fatal(1,"No-TM1638 lab widths");
        check_buttons(2'b01);
        check_buttons(2'b10);
        check_buttons(2'b11);
        check_buttons(2'b00);
        `else
        btn[1]=1;
        repeat(3) @(negedge dut.clk);
        if(dut.key[0]!==1) $fatal(1,"BTN1 mapping");
        btn[1]=0;
        `endif

        // Wait for the next visible frame origin, then count a whole raster.
        wait(dut.i_vga.vpos==1);
        wait(dut.i_vga.hpos==0 && dut.i_vga.vpos==0);
        @(negedge dut.clk);
        cycles=0; pixels=0; active_pixels=0; hs_pixels=0; vs_lines=0;
        last_x=-1;last_y=-1;
        repeat(H_TOTAL*525*PIXEL_DIV) begin
            if(dut.i_vga.hpos!=last_x || dut.i_vga.vpos!=last_y) begin
                pixels=pixels+1;
                if(ja[7] !== !(dut.i_vga.hpos >= H_ACTIVE+H_FRONT &&
                              dut.i_vga.hpos < H_ACTIVE+H_FRONT+H_SYNC) ||
                   ja[3] !== !(dut.i_vga.vpos >= 490 && dut.i_vga.vpos < 492))
                    $fatal(1,"Sync position/polarity");
                if(dut.i_vga.display_on !== (dut.i_vga.hpos < H_ACTIVE && dut.i_vga.vpos < 480))
                    $fatal(1,"Active video window");
                if(dut.i_vga.display_on && (dut.x != dut.i_vga.hpos || dut.y != dut.i_vga.vpos))
                    $fatal(1,"Lab coordinates");
                if(dut.i_vga.display_on) begin
                    active_pixels=active_pixels+1;
                    if({ja[4],ja[0]}!==2'b01 || {ja[5],ja[1]}!==2'b10 || {ja[6],ja[2]}!==2'b11)
                        $fatal(1,"TinyVGA colour mapping");
                end else if({ja[6:4],ja[2:0]}!==6'b0)
                    $fatal(1,"RGB must be black during blanking");
                if(!ja[7]) hs_pixels=hs_pixels+1;
                if(dut.i_vga.hpos==0 && !ja[3]) vs_lines=vs_lines+1;
                last_x=dut.i_vga.hpos;last_y=dut.i_vga.vpos;
            end
            cycles=cycles+1;
            @(negedge dut.clk);
        end
        if(pixels!=H_TOTAL*525 || active_pixels!=H_ACTIVE*480 || hs_pixels!=H_SYNC*525 || vs_lines!=2)
            $fatal(1,"Raster: pixels=%d active=%d hs=%d vs=%d",pixels,active_pixels,hs_pixels,vs_lines);
        if(dut.mic!==MIC_SAMPLE) $fatal(1,"Microphone sample %h",dut.mic);
        if(dac_words<4) $fatal(1,"DAC clocks absent");
        if(hs_periods<525 || mic_periods<4 || dac_periods<4) $fatal(1,"Clock measurements absent");
        `ifdef CMOD_TEST_NO_TM1638
        check_buttons(2'b11);
        check_buttons(2'b00);
        `else
        btn[0]=1;#1;
        if(dut.rst!==1 || led0_r!==0) $fatal(1,"Asynchronous reset assertion");
        last_hs=0; last_mic_ws=0; last_dac_ws=0;
        #500;btn[0]=0;
        repeat(2) @(negedge dut.clk);
        if(dut.rst!==1) $fatal(1,"Button reset released too early");
        wait(dut.rst===0);
        `endif
        `ifndef CMOD_TEST_NO_PLL
        force dut.i_mmcm.LOCKED=0;#1;
        if(dut.rst!==1) $fatal(1,"Lock loss reset");
        last_hs=0; last_mic_ws=0; last_dac_ws=0;
        force dut.i_mmcm.LOCKED=1;
        repeat(2) @(negedge dut.clk);
        if(dut.rst!==1) $fatal(1,"Lock-loss reset released too early");
        repeat(2) @(negedge dut.clk);
        if(dut.rst!==0) $fatal(1,"Lock-loss reset recovery");
        release dut.i_mmcm.LOCKED;
        `endif
        $display("PASS: %0dx480, reset, GPIO/UART, full VGA frame, blanking, INMP441, I2S DAC", H_ACTIVE);
        $finish;
    end
endmodule
